/**
 * @method
 * @name isInArr
 * @description desc
 * @param {string} s desc
 * @param {string} arr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isInArr = function(s, arr) {
    for (var i = 0; i < arr.length; i++) {
        if (s == arr[i]) {
            return true;
        }
    }
    return false;
};
/**
 * @method
 * @name isDate0
 * @description desc
 * @param {string} d desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDate0 = function(d) {
    var dte = new Date(0, 0, 0);
    return (d.toString() == dte.toString());
};
/**
 * @method
 * @name fn_incMth
 * @description desc
 * @param {string} sd desc
 * @param {string} inc desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_incMth = function(sd, inc) {
    var y = sd.getFullYear(),
        m = sd.getMonth(),
        d = sd.getDate();
    var ld = new Date(y, m + 1, 0); // 기준월의 마지막일자
    var rd;
    if (ld.getDate() == sd.getDate()) {
        // 기준일의 일자가 마지막 일자이면 더해진 대상월의 마지막일자를 반환한다.
        // m+inc 는 대상월이며 m+inc는 대상월의 다음월이나 일자가 0이면 이전월의 마지막일자를 반환한다.
        // 원소스인 델파이에서는 '20080229' 의 1월 더한 값은 '20080329' 이다.
        rd = new Date(y, m + inc + 1, 0);
        if (rd.getDate() > sd.getDate()) {
            rd = new Date(rd.getFullYear(), rd.getMonth(), sd.getDate());
        }
    } else {
        rd = new Date(y, m + inc, d);
    }
    return rd;
};
/**
 * @method
 * @name fn_incDte
 * @description desc
 * @param {string} d desc
 * @param {string} t desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_incDte = function(d, t) {
    d.setDate(d.getDate() + t);
    return d;
};


// 경과개월수 산출
/**
 * @method
 * @name fn_difMth
 * @description desc
 * @param {string} bgn desc
 * @param {string} end desc
 * @param {string} curDte desc
 * @param {string} alwDte desc
 * @param {string} fbdBgn desc
 * @param {string} fbdEnd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_difMth = function(bgn, end, curDte, alwDte, fbdBgn, fbdEnd) {
    var result = 0;
    scwin.debug("end:" + scwin.fn_dte2str(end) + ",curDte:" + scwin.fn_dte2str(curDte) + ",alwDte:" + scwin.fn_dte2str(alwDte));
    if (end > curDte) {
        for (;
            (alwDte <= curDte) && (alwDte > 0);) {
            if (scwin.isDate0(fbdBgn) || scwin.isDate0(fbdEnd) || (alwDte < fbdBgn) || (alwDte > fbdEnd)) {
                scwin.debug("alwDte:" + scwin.fn_dte2str(alwDte) + ",fbdEnd:" + scwin.fn_dte2str(fbdEnd));
                result++;
            }
            scwin.debug("1.alwDte:" + scwin.fn_dte2str(alwDte));
            alwDte = scwin.fn_incMth(alwDte, 1);
            scwin.debug("2.alwDte:" + scwin.fn_dte2str(alwDte));
        }
    }
    return result;
};
/**
 * @method
 * @name fn_dte2str
 * @description desc
 * @param {string} d desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_dte2str = function(d) {
    if (!scwin.isDate0(d)) {
        var s = d.getFullYear().toString() + (d.getMonth() < 9 ? "0" : "") + (d.getMonth() + 1).toString() + (d.getDate() < 10 ? "0" : "") + d.getDate().toString();
        return s;
    } else {
        return "";
    }
};
/**
 * @method
 * @name fn_str2dte
 * @description desc
 * @param {string} s desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_str2dte = function(s) {
    var y = parseInt(s.substr(0, 4).replace(/^0*/g, ""));
    var m = parseInt(s.substr(4, 2).replace(/^0*/g, "")) - 1;
    var d = parseInt(s.substr(6, 2).replace(/^0*/g, ""));
    if (isNaN(y) || isNaN(m) || isNaN(d) || (m < 0) || (m > 11) || (d < 1) || (d > 31)) {
        return (new Date(0, 0, 0));
    } else {
        return (new Date(y, m, d));
    }

};


// 대상자, 사유에 따른 보호예수일부매각 금지 기간
/**
 * @method
 * @name fn_getTrdAlwMnt
 * @description desc
 * @param {string} atrTyp desc
 * @param {string} prtRsn desc
 * @param {string} rsnMng desc
 * @param {string} rsnFin desc
 * @param {string} reqDay desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getTrdAlwMnt = function(atrTyp, prtRsn, rsnMng, rsnFin, reqDay) {
    if (scwin.isInArr(atrTyp, ["1", "2"])) {
        // 최대주주,특수관계인
        if (prtRsn == "61") {
            // 신규상장
            if (reqDay < "20050127") {
                return 12;
            } else {
                return 6;
            }
        } else if (scwin.isInArr(prtRsn, ["62", "63"])) {
            // 합병,포괄적주식교환
            scwin.debug("prtRsn:" + prtRsn + ",rsnMng:" + rsnMng + ",rsnFin:" + rsnFin);
            if (rsnMng == "1") {
                return 6;
            } else
                //  경영권 변동 없음
                if (rsnMng == "2") {
                    return (rsnFin == "1" ? 12 : (rsnFin == "2" ? 24 : 0));
                }

            else
            // 경영권 변동,재무조건 충족

            {
                return 0;
            }
        } else if (scwin.isInArr(prtRsn, ["64", "65", "66"])) {
            // 영업양수&유상증자제3자배정,자산양수&유상증자제3자배정,주식스왑
            if (rsnMng == "1") {
                return 6;
            } else
                // 경영권 변동 없음
                if (rnsMng == "2") {
                    return 12;
                }

            else
            // 경영권 변동

            {
                return 0;
            }
        } else if (scwin.isInArr(prtRsn, ["67", "68"])) {
            // 감자 및 유상증자제3자배정,기타
            return 0;
        } else {
            return 0;
        }
    } else {
        return 0;
    }
};



// 일부매각가능시작일
/**
 * @method
 * @name fn_getAlwDte
 * @description desc
 * @param {string} mth desc
 * @param {string} bgn desc
 * @param {string} rsv desc
 * @param {string} chkDte desc
 * @param {string} day desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getAlwDte = function(mth, bgn, rsv, chkDte, day) {
    scwin.debug("fn_getAlwDte.bgn:" + scwin.fn_dte2str(bgn));
    if ((mth > 0) && (!scwin.isDate0(bgn))) {
        var dte = scwin.fn_incMth(bgn, mth);
        scwin.debug("fn_getAlwDte.dte:" + scwin.fn_dte2str(dte));
        // 일부매각허용일 이전에 예약매매가 발생하면 허용일은 1년 연기된다.
        if (rsv && (chkDte < dte) && (chkDte <= day)) {
            // 예약매매일이 일부매각허용일 보다 작고, 조회일이 사유발생일(예약매매일) 이후면
            dte = scwin.fn_incMth(dte, 12);
        }
        scwin.debug("fn_getAlwDte.dte:" + scwin.fn_dte2str(dte));
        return dte;
    } else {
        return (new Date(0, 0, 0));
    }
};



// 예약매매로 인한 일부매각금지 기간 산출
/**
 * @method
 * @name fn_calFbdTrm
 * @description desc
 * @param {string} bgn desc
 * @param {string} alwDte desc
 * @param {string} chkDte desc
 * @param {string} mth desc
 * @param {string} rsv desc
 * @param {string} fbdBgn desc
 * @param {string} fbdEnd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_calFbdTrm = function(bgn, alwDte, chkDte, mth, rsv, fbdBgn, fbdEnd) {
    scwin.debug("bgn:" + scwin.fn_dte2str(bgn) + ",mth:" + mth + ",chkDte:" + scwin.fn_dte2str(chkDte) + ",alwDte:" + scwin.fn_dte2str(alwDte));
    fbdBgn = ((mth > 0) && (!scwin.isDate0(bgn)) ? chkDte : alwDte);
    if ((mth > 0) && (!scwin.isDate0(bgn))) {
        if (alwDte > chkDte) {
            fbdBgn = chkDte;
        } else {
            fbdBgn = alwDte;
            for (; fbdBgn <= chkDta; scwin.fn_incMth(fbdBgn, 1)) {

            }

        }
        scwin.debug("fn_calFbdTrm.fbdBgn:" + scwin.fn_dte2str(fbdBgn) + ",chkDte:" + scwin.fn_dte2str(chkDte));
        // FbdBgn 산정시 예약매매확인 시점의 단위월기간은 일부매각 가능. FbdEnd 산정은 실제로 매매가 금지된 날(FbdBgn)으로 부터 1년으로 함.
        fbdEnd = scwin.fn_incDte(scwin.fn_incMth(fbdBgn, 12), -1);
    } else {
        fbdBgn = new Date(0, 0, 0);
        fbdEnd = new Date(0, 0, 0);
    }
    return ({
        "fbdBgn": fbdBgn,
        "fbdEnd": fbdEnd
    });
};



// array로 선언된 구성항목을 combo에 채워넣는다.
/**
 * @method
 * @name fn_filCodCtr
 * @description desc
 * @param {string} c desc
 * @param {string} cod desc
 * @param {string} inc desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_filCodCtr = function(c, cod, inc) {
    var s = "";
    for (var i = 0; i < cod.length; i++) {
        if ((inc == undefined) || scwin.isInArr(cod[i].cod, inc)) {
            s = s + (s == "" ? "" : ",") + cod[i].cod + "^" + cod[i].cap;
        }
    }
    c.cbdata = s;
    c.setDisabled(true);
    c.setSelectedIndex((s != "" ? 0 : -1));
};
/**
 * @method
 * @name p
 * @description desc
 * @param {string} i desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.p = function(i) {
    var j = parseInt(i);
    return (isNaN(j) ? 0 : j);
};


// combo에 데이터를 설정하는 부분, 6개의 컨트롤이 연관되어 있음
/**
 * @method
 * @name fn_setCodCtr
 * @description desc
 * @param {string} c desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setCodCtr = function(c) {
    var arr = new Array();
    if ((c == cmb_PrtdepoObjKindCd) || (c == cmb_PrtdepoObjTpCd)) {
        // 보호예수대상종류 선택시
        if (c == cmb_PrtdepoObjKindCd) {
            if (cmb_PrtdepoObjKindCd.bindColVal == "1") {
                arr = [];
            } else if (cmb_PrtdepoObjKindCd.bindColVal == "2") {
                arr = ["1", "2", "3", "9"];
            } else if (cmb_PrtdepoObjKindCd.bindColVal == "3") {
                arr = ["4", "5", "9"];
            } else {
                arr = [];
            }
            scwin.fn_filCodCtr(cmb_PrtdepoObjTpCd, codArrObjTyp, arr);
        }
        if (cmb_PrtdepoObjTpCd.bindColVal == "9") {
            // 보호예수대상구분기타내용의 설정
            txb_PrtdepoObjTpMiscContn.setReadOnly("");
        } else {
            txb_PrtdepoObjTpMiscContn.setValue("");
            txb_PrtdepoObjTpMiscContn.setReadOnly("readOnly");
        }
    } else if ((c == cmb_PrtdepoRsnCd) || (c == cmb_PrtdepoRsnMngrghtTpCd)) {
        // 보호예수사유 선택시
        if (c == cmb_PrtdepoRsnCd) {
            if (cmb_PrtdepoRsnCd.bindColVal == "61") {
                arr = [];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "62") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "63") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "64") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "65") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "66") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "67") {
                arr = [];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "68") {
                arr = ["3", "4", "5", "6"];
            } //68 ? 
            else if (cmb_PrtdepoRsnCd.bindColVal == "69") {
                arr = [];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "70") {
                arr = [];
            } //2008-11-27 보호예수사유코드 추가
            else if (cmb_PrtdepoRsnCd.bindColVal == "71") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "72") {
                arr = ["1", "2"];
            } else if (cmb_PrtdepoRsnCd.bindColVal == "73") {
                arr = ["1", "2"];
            } else {
                arr = ["1", "2", "3", "4", "5", "6"];
            } //유가는 다보여준다..
            scwin.fn_filCodCtr(cmb_PrtdepoRsnMngrghtTpCd, codArrRsnMng, arr);
        }
        if (cmb_PrtdepoRsnCd.bindColVal == "01" || cmb_PrtdepoRsnCd.bindColVal == "62") {
            if (cmb_PrtdepoRsnMngrghtTpCd.bindColVal == "1") {
                arr = [];
            } else if (cmb_PrtdepoRsnMngrghtTpCd.bindColVal == "2") {
                arr = ["1", "2"];
            } else {
                arr = [];
            }
        } else if (cmb_PrtdepoRsnCd.bindColVal == "02" || cmb_PrtdepoRsnCd.bindColVal == "63") {
            if (cmb_PrtdepoRsnMngrghtTpCd.bindColVal == "1") {
                arr = [];
            } else if (cmb_PrtdepoRsnMngrghtTpCd.bindColVal == "2") {
                arr = ["1", "2"];
            } else {
                arr = [];
            }
        } else {
            arr = [];
        }
        scwin.fn_filCodCtr(cmb_PrtdepoRsnFncTpCd, codArrRnsFnc, arr);
    }
};
