/**
 * @method
 * @name fn_calCtr
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_calCtr = function() {
    /* 예약매매로 인한 각 결과값들의 변경
	    1. 예약매매기간은 1년이 연장된다.
	    2. 일부매각가능일 이전에 예약매매가 발생되면, 일부매각가능일은 1년이 연기된다.
	    3. 사유발생일(예약매매일)로 부터 1년동안 경과개월수는 변동되지 않는다.
	    4. 사유발생일(예약매매일)로 부터 1년동안 당월매각가능주식수는 0이 된다. 따라서, 누적매각가능주식수, 비율등도 변동되지 않는다.
	    5. 단, 예약매매가 확인된 월의 일부매각 가능은 허용된다.
	    */
    var reqDteStr = "20071231"; // dataset 에서 가져와야 할 부분
    var reqDte = scwin.fn_str2dte(reqDteStr);
    var mth = scwin.fn_getTrdAlwMnt(cmb_PrtdepoPrnTpCd.bindColVal, cmb_PrtdepoRsnCd.bindColVal, cmb_PrtdepoRsnMngrghtTpCd.bindColVal, cmb_PrtdepoRsnFncTpCd.bindColVal, reqDte);
    scwin.debug("mth:" + mth);
    var alwDte = scwin.fn_getAlwDte(mth, scwin.fn_str2dte(med_PrtdepoStrtDd.getText()), chk_ActYn.checked, scwin.fn_str2dte(med_RsnOccrDdtm.getText()), (new Date()));
    scwin.debug("alwDte:" + scwin.fn_dte2str(alwDte));
    med_alwDd.setValue(scwin.fn_dte2str(alwDte)); // 일부매각허용일 설정

    // 예약매매로 인한 추가보호예수기간 산정.
    //fn_calFbdTrm(bgn, alwDte, chkDte, mth, rsv, fbdBgn, fbdEnd)
    scwin.debug("med_RsnOccrDdtm:" + med_RsnOccrDdtm.getText());
    var fbdDte = scwin.fn_calFbdTrm(scwin.fn_str2dte(med_PrtdepoStrtDd.getText()), alwDte, scwin.fn_str2dte(med_RsnOccrDdtm.getText()), mth, chk_ActYn.checked);
    scwin.debug("fbdDte:" + scwin.fn_dte2str(fbdDte.fbdBgn) + "," + scwin.fn_dte2str(fbdDte.fbdEnd));
    // 일부매각가능시작일로부터 현재까지의 경과 개월수
    med_pasMth.setValue(scwin.fn_difMth(scwin.fn_str2dte(med_PrtdepoStrtDd.getText()), scwin.fn_str2dte(med_PrtdepoEndDd.getText()), (new Date()), alwDte, fbdDte.fbdBgn, fbdDte.fbdEnd));
    var curDte = new Date();

    // 금월보호예수해제주식수
    if (!scwin.isDate0(scwin.fn_str2dte(med_alwDd.getText()))) {
        if (chk_ActYn.checked) {
            if (((curDte >= fbdDte.fbdBgn) && (curDte <= fbdDte.fbdEnd)) || (curDte < alwDte)) {
                med_freCurMth.setValue((0).toString());
            } else {
                med_freCurMth.setValue((scwin.p(med_PrtdepoShrs.getText()) * 0.05).toString());
            }
        } else {
            // 예약매매와 관련되지 않으면, 일부매각가능일 이후(포함)에 5% 매각가능.
            if (alwDte <= curDte) {
                med_freCurMth.setValue((scwin.p(med_PrtdepoShrs.getText()) * 0.05).toString());
            } else {
                med_freCurMth.setValue((0).toString());
            }
        }
    } else {
        med_freCurMth.setValue((0).toString());
    }

    // 누적매각가능주식수
    if (scwin.fn_str2dte(med_PrtdepoEndDd.getText()) <= curDte) {
        med_freTot.setValue(med_PrtdepoShrs.getText());
    } else {
        med_freTot.setValue(Math.min(scwin.p(med_PrtdepoShrs.getText()), (scwin.p(med_pasMth.getText()) * (scwin.p(med_PrtdepoShrs.getText()) * 0.05))));
    }

    // 누적매각가능주식비율
    if (scwin.p(med_PrtdepoShrs.getText()) == 0) {
        med_freTotRat.setValue((0).toString());
    } else {
        if (scwin.fn_str2dte(med_PrtdepoEndDd.getText()) <= curDte) {
            med_freTotRat.setValue((100).toString());
        } else {
            med_freTotRat.setValue((scwin.p(med_freTot.getText()) / scwin.p(med_PrtdepoShrs.getText()) * 100).toString());
        }
    }

    // 잔여의무보호예수주식수
    med_notFreTot.setValue(scwin.p(med_PrtdepoShrs.getText()) - scwin.p(med_freTot.getText()));
};
